-- Set (or change) the two passwords. Run in Supabase → SQL Editor AFTER schema.sql.
-- 1. Copy this snippet into the SQL Editor (do NOT edit this file in the repo).
-- 2. Replace the two placeholders with your real passwords, then Run.
-- 3. Optional: delete the query from the SQL Editor history afterwards.
-- Only bcrypt hashes are stored. Never commit real passwords.

insert into public.settings (key, value) values
  ('group_pw_hash', extensions.crypt('MOT_DE_PASSE_DU_GROUPE', extensions.gen_salt('bf'))),
  ('admin_pw_hash', extensions.crypt('MOT_DE_PASSE_ADMIN',     extensions.gen_salt('bf')))
on conflict (key) do update set value = excluded.value;

